mapper.select:
SELECT ADMIN_ID AS adminId, PASSWORD AS password,
       ADMIN_NAME AS adminName, ROLE AS role
FROM admin WHERE ADMIN_ID = #{adminId}

SELECT I.INQUIRY_ID, I.USER_ID, I.TITLE, I.CONTENT, I.INQUIRY_STATUS AS STATUS, R.CONTENT AS ANSWER, DATE_FORMAT(I.CREATED_AT, '%Y-%m-%d %H:%i') AS CREATED_AT, (SELECT GROUP_CONCAT(IMG_URL) FROM inquiry_img WHERE INQUIRY_ID = I.INQUIRY_ID) AS IMG_URLS FROM inquiry I LEFT OUTER JOIN inquiry_reply R ON I.INQUIRY_ID = R.INQUIRY_ID
AND I.INQUIRY_STATUS = #{status}
ORDER BY I.INQUIRY_ID DESC

mapper.insert:
INSERT INTO inquiry_reply (INQUIRY_ID, CONTENT, CREATED_AT)
VALUES (#{inquiryId}, #{answer}, NOW())
ON DUPLICATE KEY UPDATE CONTENT = #{answer}

mapper.select:
SELECT USER_ID AS userId, USER_NAME AS userName, EMAIL AS email, USER_PHONE AS userPhone, NICKNAME AS nickname, SOCIAL_TYPE AS socialType, GRADE_ID AS gradeId, USER_STATUS AS userStatus, POINT AS point, TOTAL_AMOUNT AS totalAmount, DATE_FORMAT(CREATED_AT, '%Y-%m-%d') AS createdAt, MARKETING_YN AS marketingYn, FROM USER
AND (USER_ID LIKE CONCAT('%', #{keyword}, '%') OR USER_NAME LIKE CONCAT('%', #{keyword}, '%'))
AND GRADE_ID = #{gradeId}
AND USER_STATUS = #{status}
AND USER_STATUS = #{userStatus}
ORDER BY CREATED_AT DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM USER


        AND (USER_ID   LIKE CONCAT('%', #{keyword}, '%')
          OR USER_NAME LIKE CONCAT('%', #{keyword}, '%'))


        AND GRADE_ID = #{gradeId}


        AND USER_STATUS = #{status}


        AND USER_STATUS = #{userStatus}

SELECT p.PRODUCT_ID, p.PRODUCT_NAME, p.PRODUCT_TYPE, p.PRICE, p.DEPOSIT, p.DESCRIPTION, p.VIEW_COUNT, p.IS_AVAILABLE, DATE_FORMAT(p.CREATED_AT, '%Y-%m-%d') AS CREATED_AT, (SELECT IMG_URL FROM product_img pi WHERE pi.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS IMG_URL, s.CAPACITY, s.SIZE, s.WEIGHT, s.MATERIAL, s.ORIGIN, f.TITLE AS FEATURE_TITLE, f.CONTENT AS FEATURE_CONTENT FROM product p LEFT JOIN product_spec s ON p.PRODUCT_ID = s.PRODUCT_ID LEFT JOIN product_feature f ON p.PRODUCT_ID = f.PRODUCT_ID
AND p.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%')
ORDER BY p.CREATED_AT DESC LIMIT #{offset}, #{pageSize}

mapper.insert:
INSERT INTO product_img (PRODUCT_ID, IMG_URL, IS_MAIN, SORT_ORDER)
VALUES (#{productId}, #{imgUrl}, 'Y', 1)
ON DUPLICATE KEY UPDATE IMG_URL = #{imgUrl}

INSERT INTO product_feature (PRODUCT_ID, TITLE, CONTENT, SORT_ORDER)
VALUES (#{productId}, #{featureTitle}, #{featureContent}, 1)
ON DUPLICATE KEY UPDATE TITLE = #{featureTitle}, CONTENT = #{featureContent}

mapper.select:
SELECT O.ORDER_ID AS ORDER_ID, O.USER_ID AS USER_ID, DATE_FORMAT(O.CREATED_AT, '%Y-%m-%d %H:%i') AS CREATED_AT, O.TOTAL_PRICE AS TOTAL_PRICE, O.ORDER_STATUS AS ORDER_STATUS, (SELECT GROUP_CONCAT(P.PRODUCT_NAME SEPARATOR ', ') FROM ORDER_ITEM OI JOIN PRODUCT P ON OI.PRODUCT_ID = P.PRODUCT_ID WHERE OI.ORDER_ID = O.ORDER_ID) AS PRODUCT_NAME, (SELECT PI.IMG_URL FROM ORDER_ITEM OI JOIN product_img PI ON OI.PRODUCT_ID = PI.PRODUCT_ID WHERE OI.ORDER_ID = O.ORDER_ID ORDER BY PI.IS_MAIN DESC LIMIT 1) AS IMG_URL FROM ORDERS O
AND (O.ORDER_ID LIKE CONCAT('%', #{keyword}, '%') OR O.USER_ID LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY O.CREATED_AT DESC LIMIT #{offset}, #{pageSize}

SELECT C.*, I.IMG_URL FROM camp C
LEFT JOIN camp_img I ON C.CAMP_ID = I.CAMP_ID AND I.IS_MAIN = 'Y'
WHERE C.CAMP_ID = #{campId}

mapper.update:
UPDATE camp SET CAMP_NAME = #{campName}, ADDRESS = #{campAddress},
                INDUTY = #{campType}, DESCRIPTION = #{campContent}
WHERE CAMP_ID = #{campId}

UPDATE event
SET TITLE = #{title}, CONTENT = #{content},
    START_DATE = #{start_date}, END_DATE = #{end_date}
WHERE EVENT_ID = #{eventId}

mapper.select:
SELECT A.ALARM_ID AS alarmId, A.USER_ID AS userId, A.TYPE AS type, A.TITLE AS title, A.CONTENT AS content, A.LINK_ID AS linkId, A.LINK_URL AS linkUrl, A.IS_READ AS isRead, DATE_FORMAT(A.CREATED_AT, '%m/%d %H:%i') AS createdAt FROM alarm A
AND A.TYPE = #{type}
ORDER BY A.ALARM_ID DESC LIMIT #{offset}, #{pageSize}
